import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Adv","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/adv.md","filePath":"03-developer/models/adv.md"}`),a={name:`03-developer/models/adv.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="adv" tabindex="-1">Adv <a class="header-anchor" href="#adv" aria-label="Permalink to “Adv”">​</a></h1><p>Model reference · <code>App\\Models\\Adv</code></p><h3 id="_1-model" tabindex="-1">1. Model <a class="header-anchor" href="#_1-model" aria-label="Permalink to “1. Model”">​</a></h3><p>The site advertising management model; used to store ad information, image, destination link, click limit, and publication status.</p><h3 id="_2-table-advs" tabindex="-1">2. Table: <code>advs</code> <a class="header-anchor" href="#_2-table-advs" aria-label="Permalink to “2. Table: advs”">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Comment</th></tr></thead><tbody><tr><td><code>id</code></td><td>bigint unsigned</td><td>No</td><td>Ad ID</td></tr><tr><td><code>title</code></td><td>varchar(255)</td><td>No</td><td>Ad title</td></tr><tr><td><code>expire</code></td><td>date</td><td>No</td><td>Ad expiration date</td></tr><tr><td><code>image</code></td><td>varchar(255)</td><td>No</td><td>Ad image name or path</td></tr><tr><td><code>max_click</code></td><td>int unsigned</td><td>No</td><td>Maximum permitted number of clicks; default value <code>0</code></td></tr><tr><td><code>click</code></td><td>int unsigned</td><td>No</td><td>Number of recorded clicks; default value <code>0</code></td></tr><tr><td><code>status</code></td><td>tinyint(1)</td><td>No</td><td>Ad status; default value <code>0</code></td></tr><tr><td><code>link</code></td><td>varchar(255)</td><td>No</td><td>Ad destination link</td></tr><tr><td><code>user_id</code></td><td>bigint unsigned</td><td>No</td><td>ID of the user who registered or owns the ad</td></tr><tr><td><code>deleted_at</code></td><td>timestamp</td><td>Yes</td><td>Soft deletion time</td></tr><tr><td><code>created_at</code></td><td>timestamp</td><td>Yes</td><td>Creation time</td></tr><tr><td><code>updated_at</code></td><td>timestamp</td><td>Yes</td><td>Last modification time</td></tr></tbody></table><h3 id="_3-extra-description-of-table-fields" tabindex="-1">3. Extra description of table fields <a class="header-anchor" href="#_3-extra-description-of-table-fields" aria-label="Permalink to “3. Extra description of table fields”">​</a></h3><p><strong><code>advs.title</code></strong></p><p>Stores the ad title.</p><p><strong><code>advs.expire</code></strong></p><p>Specifies the ad expiration date. In the system&#39;s logic, an ad may or may not have a specific expiration date; however, the database column is <code>NOT NULL</code>, so note that the current Schema does not allow the date to be absent.</p><p>This field is cast to the <code>date</code> type using the model&#39;s <code>casts</code>.</p><p><strong><code>advs.image</code></strong></p><p>Stores the ad image name or path. Model images are stored in separate, categorized paths.</p><p>The <code>imgUrl()</code> method returns the usable image URL. If the image does not exist, the site&#39;s default logo at <code>assets/upload/logo.svg</code> is displayed.</p><p><strong><code>advs.max_click</code></strong></p><p>Specifies the maximum permitted number of clicks for the ad. If this constraint is set and the number of clicks reaches the specified limit, the ad is disabled.</p><p>The default value of this field is <code>0</code>. The precise meaning of zero, including whether it disables the constraint or allows no clicks for the ad, depends on the implementation logic.</p><p><strong><code>advs.click</code></strong></p><p>Stores the number of clicks recorded for the ad. This value increases when users click the ad and is used to check the <code>max_click</code> constraint.</p><p><strong><code>advs.status</code></strong></p><p>Specifies the ad status. This field is used in the system to distinguish between statuses such as active, inactive, draft, and under review.</p><p>A value of <code>0</code> or <code>false</code> indicates an inactive status. The interpretation of other values depends on the status logic defined in the system.</p><p><strong><code>advs.link</code></strong></p><p>Stores the ad destination link. A user&#39;s click is first redirected through the main site so the click can be recorded and counted in the system; the user is then redirected to the ad&#39;s external destination.</p><p><strong><code>advs.user_id</code></strong></p><p>Identifies the user who registered or owns the ad. This field references the <code>users</code> table.</p><p>Related model documentation: <a href="./user.html">User</a>.</p><p>Deleting the user associated with the ad is not permitted due to the database&#39;s <code>ON DELETE RESTRICT</code> constraint.</p><p><strong><code>advs.deleted_at</code></strong></p><p>Used for soft deletion (Soft Delete).</p><h3 id="_4-methods" tabindex="-1">4. Methods <a class="header-anchor" href="#_4-methods" aria-label="Permalink to “4. Methods”">​</a></h3><p><strong><code>imgUrl()</code></strong></p><p>Returns the ad image URL. The image is retrieved from the storage path for ads. If the image does not exist, the site&#39;s default logo at <code>assets/upload/logo.svg</code> is returned.</p>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};